    pharmacologySubject: "Chemotherapy & Antimicrobial Pharmacology",
    specialty: "Infectious Diseases",
    disease: "Malaria",
    title: "Severe Falciparum Malaria with Cerebral Involvement — Variant 13",
    difficulty: "Advanced",
    demographics: "Alice Kipkorir, 71-year-old female, 61 kg, Social Worker from Kisumu",
    chiefComplaint: "High fever, confusion, and inability to wake for 12 hours",
    hpi: "Alice Kipkorir, a 71-year-old Social Worker from Kisumu, was brought by family with a 3-day history of high fever (39-40°C), chills, severe headache, and muscle aches. Over the past 12 hours became confused, difficult to rouse, and has not eaten or drunk. Lives in a malaria-endemic area with recent rains. Has not used mosquito nets consistently.",
    pmh: "No significant PMH. No prior severe malaria. No known G6PD deficiency.. Also has Hypertension.",
    medHx: "No regular medications. Took paracetamol for fever.",
